    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(address a, address b) public {
        bool ret1 = c.setOwner(a); if (__ESBMC_reverted()) return;
        bool ret2 = c.setOwner(b); if (__ESBMC_reverted()) return;
        bool ret3 = c.setOwner(a); if (__ESBMC_reverted()) return;
        assert(ret1 && ret2 && ret3 && c.owner() == a);
